Lemma put_X_hi : forall P E L es A k lo,
  elems_ok L -> (forall x s, In (x, s) es -> 0 < x /\ x + 24 + s <= hceil /\ (x + 24 + s <= 0x10000 \/ 0xb8000 <= x)) ->
  hceil <= lo -> 0xb8000 <= lo -> lo <= A -> (A + k <= P \/ P + 242 <= A) -> (A + k <= E \/ E + 24 <= A) ->
  Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (put_X P E L es).
Proof.
  intros P E L es A k lo EL ESH CEIL IMG LA DP DE. unfold put_X, G_HTTP_CAT, G_FIELD_TABLE.
  constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|].
  apply Forall_app. split.
  - apply elemsW_hi; [exact EL | lia].
  - apply mb_elemsW_Forall_sep. intros x s IN. destruct (ESH x s IN) as (_ & K & _). lia.
Qed.

(* [comment removed for export] *)
Lemma put_X_heap : forall P E L es A k (LB : list block) SP lo,
  (forall e, e ∈ L -> forall a n, rclient_range LB SP a n -> 0 <= n -> a + n <= e \/ e + 48 <= a) ->
  (forall x s, In (x, s) es -> forall a n, rclient_range LB SP a n -> 0 <= n -> a + n <= x \/ x + 24 + s <= a) ->
  rclient_range LB SP A k -> 0 <= k -> A + k <= hceil -> hceil <= lo -> 0xb8000 <= lo -> lo <= P -> lo <= E ->
  (A + k <= 0x10000 \/ 0xb8000 <= A) ->
  Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (put_X P E L es).
Proof.
  intros P E L es A k LB SP lo FL FB RC K0 AH CEIL IMG LP LE ST. unfold put_X, G_HTTP_CAT, G_FIELD_TABLE.
  constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|].
  apply Forall_app. split.
  - apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (e & Euv & INe). injection Euv as <- <-. cbn.
    destruct (FL e ltac:(apply (proj2 (list_elem_of_In _ _)); exact INe) A k RC K0); lia.
  - apply mb_elemsW_Forall_sep. intros x s IN. destruct (FB x s IN A k RC K0); lia.
Qed.

