Lemma put_X_static : forall P E L es A k lo,
  elems_ok L -> (forall x s, In (x, s) es -> 0 < x /\ x + 24 + s <= hceil /\ (x + 24 + s <= 0x10000 \/ 0xb8000 <= x)) ->
  0xb8000 <= lo -> lo <= P -> lo <= E -> 0x10000 <= A -> A + k <= 0x95050 ->
  Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (put_X P E L es).
Proof.
  intros P E L es A k lo EL ESH IMG LP LE A0 AK. unfold put_X, G_HTTP_CAT, G_FIELD_TABLE.
  constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|].
  apply Forall_app. split.
  - apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (e & Euv & INe). injection Euv as <- <-. cbn.
    destruct (EL e ltac:(apply (proj2 (list_elem_of_In _ _)); exact INe)) as (K1 & K2 & K3). lia.
  - apply mb_elemsW_Forall_sep. intros x s IN. destruct (ESH x s IN) as (_ & _ & K). lia.
Qed.

(* [comment removed for export] *)
Lemma put_X_fbblk : forall P E L es (FB : fbv) lo,
  (forall e, e ∈ L -> e + 48 <= fb_begin FB \/ fb_end FB <= e) ->
  (forall x s, In (x, s) es -> x + 24 + s <= fb_begin FB \/ fb_end FB <= x) ->
  fb_end FB <= hceil -> hceil <= lo -> lo <= P -> lo <= E -> (fb_end FB <= 0x10000 \/ 0xb8000 <= fb_begin FB) -> fb_begin FB <= fb_end FB ->
  Forall (fun iv : Z * Z => fb_end FB <= fst iv \/ snd iv <= fb_begin FB) (put_X P E L es).
Proof.
  intros P E L es FB lo DL DB FE CEIL LP LE QLO BE. unfold put_X, G_HTTP_CAT, G_FIELD_TABLE.
  constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor; [cbn; lia|].
  apply Forall_app. split.
  - apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (e & Euv & INe). injection Euv as <- <-. cbn.
    destruct (DL e ltac:(apply (proj2 (list_elem_of_In _ _)); exact INe)); lia.
  - clear - DB. induction es as [|[x s] es IH]; [constructor|]. cbn. constructor.
    + cbn. destruct (DB x s ltac:(left; reflexivity)); lia.
    + apply IH. intros x' s' IN. apply DB. right. exact IN.
Qed.

